#!/bin/sh
# Writes a commit message generated by Claude Code into $1.
# Called only when the author gave no message (see prepare-commit-msg-check.sh).

COMMIT_MSG_FILE="${1:-.git/COMMIT_EDITMSG}"

# Check if Claude Code CLI is installed
if ! command -v claude >/dev/null 2>&1; then
  echo "Claude Code CLI not found, skipping commit message generation."
  exit 0
fi

# Get the list of staged files
STAGED_FILES=$(git diff --cached --name-only)

# Exit if there are no staged files
if [ -z "$STAGED_FILES" ]; then
  exit 0
fi

# Form the prompt for Claude
PROMPT="git-agent desc commit en $STAGED_FILES"

# Generate commit message via Claude Code CLI (non-interactive)
COMMIT_TEXT=$(printf "%s\n" "$PROMPT" | claude -p)

# Drop ``` fence lines and blank lines at the start and end. Blank lines inside
# are kept: the one after the first line is what makes it the commit title.
COMMIT_TEXT=$(printf "%s\n" "$COMMIT_TEXT" | sed '/^```/d' | awk 'NF {found=1} found' \
  | awk '{lines[NR]=$0} NF {last=NR} END {for (i = 1; i <= last; i++) print lines[i]}')

# Exit if the generated text is empty
if [ -z "$COMMIT_TEXT" ]; then
  exit 0
fi

# Keep git's comment lines (# Please enter the commit message…) below the message
COMMENTS=$(grep '^#' "$COMMIT_MSG_FILE" 2>/dev/null || true)
{
  printf "%s\n" "$COMMIT_TEXT"
  if [ -n "$COMMENTS" ]; then
    printf "\n%s\n" "$COMMENTS"
  fi
} > "$COMMIT_MSG_FILE"
